/// Sect printed on the card (rulebook "Vampiric Sects").
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Sect {
    Camarilla,
    Anarch,
    Independent,
    Sabbat,
    /// A legacy sect (rulebook "Other Vampire Sects").
    Laibon,
}

/// A title, printed or granted by a card. Prince, Baron and Archbishop of the
/// same city contest each other; each clan's Justicar and Inner Circle
/// member is unique; primogen is not unique. `Independent`: a unique
/// Independent title a card names, worth its votes (Saulot's Guiding
/// Wisdom); no V5 vampire prints one.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Title {
    None,
    Primogen,
    Prince(&'static str),
    Baron(&'static str),
    Justicar(&'static str),
    InnerCircle(&'static str),
    Archbishop(&'static str),
    /// Sabbat titles that are not unique (bishop 1 vote, cardinal 3; a
    /// priscus votes in the prisci block) and the unique regent (4).
    Bishop,
    Cardinal,
    Priscus,
    Regent,
    /// The Laibon magaji: 2 votes, not unique (rulebook "Laibon").
    Magaji,
    /// "n votes (titled)" printed on an Independent vampire (Arishat,
    /// Scout Youngwood): a title worth n votes, not unique.
    Votes(u8),
    Independent {
        name: &'static str,
        votes: u8,
    },
    /// A unique Laibon title a card names, worth its votes (Osebo Kholo).
    Laibon {
        name: &'static str,
        votes: u8,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct CryptCard {
    pub id: u32,
    /// Printed name: the contest identity (the `(Gn)` suffix is KRCG's).
    pub name: &'static str,
    pub capacity: u8,
    /// Its crypt group; 0 for a vampire of any group (Anarch Convert).
    pub group: u8,
    /// The clan; an imbued's creed.
    pub clan: &'static str,
    /// Disciplines as printed: lower case = basic, upper case = superior;
    /// an imbued's virtues.
    pub disciplines: &'static [&'static str],
    /// `None` for an imbued.
    pub sect: Option<Sect>,
    /// An imbued (rulebook "Appendix: Imbued Rules"): a mortal ally, its
    /// capacity its cost and starting life.
    pub imbued: bool,
    pub title: Title,
    /// The title an advanced vampire holds only merged ("[MERGED] Baron of
    /// London", Appolonius): it takes precedence over the printed one.
    pub merged_title: Option<Title>,
    /// An advanced vampire (KRCG `adv`): the same vampire as its base
    /// card for contests (rulebook "Advanced Vampires").
    pub adv: bool,
    /// The Sabbat path printed on the vampire (KRCG `path`), the one it
    /// follows as it enters play.
    pub path: Option<&'static str>,
    /// "Infernal.": it does not unlock as normal; its controller may burn
    /// 1 pool in their unlock phase to unlock it (rulebook "Infernal").
    pub infernal: bool,
    /// "Black Hand." (Elimelech): a trait cards read.
    pub black_hand: bool,
    /// "Seraph." (Appius Claudius Corvus): a Black Hand trait, not a
    /// title (KRCG gives none); Tattoo Signal requires one.
    pub seraph: bool,
    /// Unique, unless printed "Non-unique." (Valkyrie) or "Tupdogs are not
    /// unique." (Tupdog): copies of a
    /// non-unique vampire do not contest.
    pub unique: bool,
    /// "Blood cursed." (Alu, Wise Frog): it cannot commit diablerie
    /// (rulebook "Traits").
    pub blood_cursed: bool,
    /// "Scarce." (Le Dinh Tho): influenced out, 3 pool burned for each
    /// vampire of its clan already controlled (rulebook "Traits").
    pub scarce: bool,
    /// "Sterile." (Effie Lowery): it cannot perform actions to put new
    /// vampires in play (rulebook "Traits").
    pub sterile: bool,
    /// "Red List." (Enkidu, The Noah): any Methuselah may mark it in
    /// their master phase and enter combat with it (rulebook "Traits").
    pub red_list: bool,
    /// A Blood Brother's printed circle ("Torrance Circle:", "Kiev
    /// circle."); `None`: a circle of one (LSJ 20020609), New Blood's
    /// chosen as he enters play.
    pub circle: Option<&'static str>,
    /// "Tremere slave" (Porphyry, Tupdog): the clan it is enslaved to
    /// (rulebook "Slave").
    pub slave: Option<&'static str>,
}

